-- The exercise bank is gone: bank exercises that are in no workout and no session are deleted.
-- Images now live in the database (ExerciseImage) and are served by the API; the drawings of the
-- exercises that stay are copied below.
-- Drawings: Everkinetic (https://github.com/everkinetic/data), CC BY-SA 4.0.

DELETE FROM "Exercise" e
WHERE e."bankKey" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "WorkoutItem" wi WHERE wi."exerciseId" = e."id")
  AND NOT EXISTS (SELECT 1 FROM "SessionExercise" se WHERE se."exerciseId" = e."id");

-- CreateTable
CREATE TABLE "ExerciseImage" (
    "exerciseId" TEXT NOT NULL,
    "mime" TEXT NOT NULL,
    "data" BYTEA NOT NULL,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ExerciseImage_pkey" PRIMARY KEY ("exerciseId")
);

-- AddForeignKey
ALTER TABLE "ExerciseImage" ADD CONSTRAINT "ExerciseImage_exerciseId_fkey" FOREIGN KEY ("exerciseId") REFERENCES "Exercise"("id") ON DELETE CASCADE ON UPDATE CASCADE;

INSERT INTO "ExerciseImage" ("exerciseId", "mime", "data", "updatedAt")
SELECT e."id", 'image/svg+xml', convert_to(v.svg, 'UTF8'), CURRENT_TIMESTAMP
